+  var cx = W / 2,
+    cy = H / 2;
+  var r = Math.min(cx, cy) - 28;
+  var n = values.length;
+  var colors = ["#c4803a", "#5a8ab4", "#5aaa5a", "#9b74b8", "#d4a017"];
+
+  function pt(i, radius) {
+    var angle = (i / n) * 2 * Math.PI - Math.PI / 2;
+    return {
+      x: cx + radius * Math.cos(angle),
+      y: cy + radius * Math.sin(angle),
