+  ctx.lineWidth = 2;
+  ctx.stroke();
+
+  // Data points
+  values.forEach(function (v, i) {
+    var dp = pt(i, r * Math.min(v / maxVal, 1));
+    ctx.beginPath();
+    ctx.arc(dp.x, dp.y, 3.5, 0, Math.PI * 2);
+    ctx.fillStyle = colors[i] || "#4a9e5c";
