693	/** 资产折线图 (Canvas) */
694	function drawAssetLineChart(canvas, data) {
695	  var ctx = canvas.getContext("2d");
696	  var W = canvas.width,
697	    H = canvas.height;
698	  ctx.clearRect(0, 0, W, H);
699	
700	  var pad = { t: 18, r: 10, b: 24, l: 52 };
701	  var cw = W - pad.l - pad.r,
702	    ch = H - pad.t - pad.b;
703	
704	  if (!data || data.length < 2) {
705	    ctx.fillStyle = "#aaa";
706	    ctx.font = "12px sans-serif";
707	    ctx.textAlign = "center";
708	    ctx.fillText("数据积累中（每天结束后记录一次）", W / 2, H / 2);
709	    return;
710	  }
711	
712	  var values = data.map(function (d) {
713	    return d.value;
714	  });
715	  var maxV = Math.max.apply(null, values) * 1.15 || 1000;
716	  var minV = Math.min(0, Math.min.apply(null, values) * 0.9);
717	
718	  function tx(i) {
719	    return pad.l + (i / (data.length - 1)) * cw;
720	  }
721	  function ty(v) {
722	    return pad.t + (1 - (v - minV) / (maxV - minV)) * ch;
723	  }
724	
725	  // Grid & Y-axis labels
726	  ctx.font = "9px sans-serif";
727	  ctx.textAlign = "right";
728	  for (var g = 0; g <= 4; g++) {
729	    var gy = pad.t + (g / 4) * ch;
730	    ctx.strokeStyle = "rgba(0,0,0,0.07)";
731	    ctx.lineWidth = 1;
732	    ctx.beginPath();
733	    ctx.moveTo(pad.l, gy);
734	    ctx.lineTo(W - pad.r, gy);
735	    ctx.stroke();
736	    var lv = maxV - (g / 4) * (maxV - minV);
737	    ctx.fillStyle = "#999";
738	    ctx.fillText(
739	      "¥" + (lv >= 1000 ? (lv / 1000).toFixed(1) + "k" : Math.round(lv)),
740	      pad.l - 4,
741	      gy + 3,
742	    );
743	  }
744	
745	  // Area fill
746	  ctx.beginPath();
747	  ctx.moveTo(tx(0), ty(data[0].value));
748	  data.forEach(function (d, i) {
749	    ctx.lineTo(tx(i), ty(d.value));
750	  });
751	  ctx.lineTo(tx(data.length - 1), pad.t + ch);
752	  ctx.lineTo(tx(0), pad.t + ch);
753	  ctx.closePath();
754	  ctx.fillStyle = "rgba(74,158,92,0.12)";
755	  ctx.fill();
756	
757	  // Line
758	  ctx.beginPath();
759	  data.forEach(function (d, i) {
760	    if (i === 0) ctx.moveTo(tx(0), ty(d.value));
761	    else ctx.lineTo(tx(i), ty(d.value));
762	  });
763	  ctx.strokeStyle = "#4a9e5c";
764	  ctx.lineWidth = 2;
765	  ctx.lineJoin = "round";
766	  ctx.stroke();
767	
768	  // Last point dot
769	  var last = data[data.length - 1];
770	  ctx.beginPath();
771	  ctx.arc(tx(data.length - 1), ty(last.value), 4, 0, Math.PI * 2);
772	  ctx.fillStyle = "#4a9e5c";
773	  ctx.fill();
774	
775	  // X-axis day labels
776	  var step = Math.max(1, Math.ceil(data.length / 7));
777	  ctx.textAlign = "center";
778	  ctx.fillStyle = "#aaa";
779	  data.forEach(function (d, i) {
780	    if (i % step === 0 || i === data.length - 1) {
781	      ctx.fillText("D" + d.day, tx(i), H - 5);
782	    }
783	  });
784	}
