786	/** 属性雷达图 (Canvas) */
787	function drawRadarChart(canvas, values, labels, maxVal) {
788	  var ctx = canvas.getContext("2d");
789	  var W = canvas.width,
790	    H = canvas.height;
791	  ctx.clearRect(0, 0, W, H);
792	
793	  var cx = W / 2,
794	    cy = H / 2;
795	  var r = Math.min(cx, cy) - 28;
796	  var n = values.length;
797	  var colors = ["#c4803a", "#5a8ab4", "#5aaa5a", "#9b74b8", "#d4a017"];
798	
799	  function pt(i, radius) {
800	    var angle = (i / n) * 2 * Math.PI - Math.PI / 2;
801	    return {
802	      x: cx + radius * Math.cos(angle),
803	      y: cy + radius * Math.sin(angle),
804	    };
805	  }
806	
807	  // Grid rings
808	  [0.25, 0.5, 0.75, 1.0].forEach(function (f) {
809	    ctx.beginPath();
810	    for (var i = 0; i < n; i++) {
811	      var p = pt(i, r * f);
812	      if (i === 0) ctx.moveTo(p.x, p.y);
813	      else ctx.lineTo(p.x, p.y);
814	    }
815	    ctx.closePath();
816	    ctx.strokeStyle = "rgba(0,0,0,0.09)";
817	    ctx.lineWidth = 1;
818	    ctx.stroke();
819	  });
820	
821	  // Axis lines
822	  for (var i = 0; i < n; i++) {
823	    var ep = pt(i, r);
824	    ctx.beginPath();
825	    ctx.moveTo(cx, cy);
826	    ctx.lineTo(ep.x, ep.y);
827	    ctx.strokeStyle = "rgba(0,0,0,0.12)";
828	    ctx.lineWidth = 1;
829	    ctx.stroke();
830	  }
831	
832	  // Data polygon
833	  ctx.beginPath();
834	  values.forEach(function (v, i) {
835	    var p = pt(i, r * Math.min(v / maxVal, 1));
836	    if (i === 0) ctx.moveTo(p.x, p.y);
837	    else ctx.lineTo(p.x, p.y);
838	  });
839	  ctx.closePath();
840	  ctx.fillStyle = "rgba(74,158,92,0.18)";
841	  ctx.fill();
842	  ctx.strokeStyle = "#4a9e5c";
843	  ctx.lineWidth = 2;
844	  ctx.stroke();
845	
846	  // Data points
847	  values.forEach(function (v, i) {
848	    var dp = pt(i, r * Math.min(v / maxVal, 1));
849	    ctx.beginPath();
850	    ctx.arc(dp.x, dp.y, 3.5, 0, Math.PI * 2);
851	    ctx.fillStyle = colors[i] || "#4a9e5c";
852	    ctx.fill();
853	  });
854	
855	  // Labels
856	  ctx.font = "bold 11px sans-serif";
857	  ctx.textAlign = "center";
858	  ctx.textBaseline = "middle";
859	  labels.forEach(function (lbl, i) {
860	    var lp = pt(i, r + 16);
861	    ctx.fillStyle = colors[i] || "#666";
862	    ctx.fillText(lbl, lp.x, lp.y);
863	  });
864	}
