    getAllSlots,
    getAllSlotsWithEmpty,
    exportSave,
    importSave,
    NUM_SLOTS,
    SLOT_PREFIX,
    AUTO_SAVE_KEY,
    INDEX_KEY,
    slotKey,
    getSaveIndex,
    setSaveIndex,
  });
}
